import React from "react";

const RejectBookingModal = ({
  booking,
  reason,
  loading,
  onReasonChange,
  onClose,
  onSubmit
}) => {
  if (!booking) {
    return null;
  }

  const resourceLabel = booking.resource?.floor
    ? `${booking.resource.name} - ${booking.resource.floor}`
    : booking.resource?.name;

  return (
    <div className="modal-backdrop" role="presentation" onClick={onClose}>
      <div className="modal-card" role="dialog" aria-modal="true" onClick={(event) => event.stopPropagation()}>
        <div className="modal-header">
          <div>
            <h3>Reject Booking</h3>
            <p>{resourceLabel || `Booking #${booking.id}`}</p>
          </div>
          <button type="button" className="icon-button" onClick={onClose}>
            Close
          </button>
        </div>

        <label className="modal-field">
          <span>Reason</span>
          <textarea
            value={reason}
            onChange={(event) => onReasonChange(event.target.value)}
            rows="5"
            placeholder="Enter rejection reason"
            required
          />
        </label>

        <div className="form-actions">
          <button type="button" className="secondary-button" onClick={onClose}>
            Cancel
          </button>
          <button
            type="button"
            className="mini-button reject"
            disabled={!reason.trim() || loading}
            onClick={onSubmit}
          >
            {loading ? "Saving..." : "Submit"}
          </button>
        </div>
      </div>
    </div>
  );
};

export default RejectBookingModal;
